import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { phoneSalesConfig } from '../config/config';
import { phonePlans } from '../config/phonePlanConfig';
import PhoneSalesDataSearchForm from './PhoneSalesDataSearchForm';
import PhoneSalesForm from './PhoneSalesForm';
import PhoneSalesResult from './PhoneSalesResult';

export default function PhoneSalesCalculator() {
  const navigate = useNavigate();
  const { penaltyRate } = phoneSalesConfig;

  const [values, setValues] = useState({
    dataFilter: '',
    category: '',
    planId: '',
    planCost: 0,
    devicePrice: 0,
    subsidy: 0,
    installments: 24,
  });
  const [results, setResults] = useState({ totalMonthly: 0, penalty: 0 });

  // 데이터 선택
  const handleDataSelect = dataFilter => {
    setValues(prev => ({ ...prev, dataFilter, category: '', planId: '', planCost: 0 }));
  };
  // 카테고리 선택
  const handleCategorySelect = category => {
    setValues(prev => ({ ...prev, category, planId: '', planCost: 0 }));
  };
  // 요금제 선택
  const handlePlanSelect = planId => {
    const plan = phonePlans.find(p => p.id === planId);
    if (plan) setValues(prev => ({ ...prev, planId, planCost: plan.monthlyFee }));
  };
  // 입력 변경
  const handleChange = e => {
    const { name, value } = e.target;
    setValues(prev => ({ ...prev, [name]: Number(value) }));
  };

  // 계산
  useEffect(() => {
    const { devicePrice, subsidy, planCost, installments } = values;
    if (!planCost) return;
    const netPrice = devicePrice - subsidy;
    const monthlyTotal = Math.round(netPrice / installments + planCost);
    const penaltyAmt = Math.ceil(installments * monthlyTotal * penaltyRate);
    setResults({ totalMonthly: monthlyTotal, penalty: penaltyAmt });
  }, [values, penaltyRate]);

  return (
    <div className="flex flex-col items-center min-h-screen bg-gray-50 p-4">
      <div className="w-full max-w-lg bg-white shadow rounded-2xl p-6 mb-4">
        <h2 className="text-2xl font-bold mb-6 text-center">
          핸드폰 판매 상담 계산기
        </h2>

        <PhoneSalesDataSearchForm
          value={values.dataFilter}
          onSelect={handleDataSelect}
        />
        <PhoneSalesForm
          values={values}
          onChange={handleChange}
          onCategorySelect={handleCategorySelect}
          onPlanSelect={handlePlanSelect}
        />
        <PhoneSalesResult {...results} />
      </div>

      <button
        type="button"
        onClick={() => navigate('/')}
        className="block mx-auto bg-gray-200 text-gray-700 rounded py-2 px-4 hover:bg-gray-300 transition"
      >
        메인 메뉴로 돌아가기
      </button>
    </div>
  );
}