import React from 'react';
import { phonePlans } from '../config/phonePlanConfig';

/**
 * PhoneSalesForm
 * 카테고리, 요금제, 가격 입력 폼
 */
export default function PhoneSalesForm({ values, onChange, onCategorySelect, onPlanSelect }) {
  // dataFilter로 요금제 필터링
  const dataFiltered = values.dataFilter
    ? phonePlans.filter(p => p.data === values.dataFilter)
    : phonePlans;
  // 고유 카테고리 목록
  const categories = Array.from(new Set(dataFiltered.map(p => p.category)));
  // 선택된 카테고리의 요금제 목록
  const categoryPlans = values.category
    ? dataFiltered.filter(p => p.category === values.category)
    : [];

  return (
    <div>
      {/* 카테고리 선택 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">카테고리</label>
        <select
          name="category"
          value={values.category}
          onChange={e => onCategorySelect(e.target.value)}
          className="w-full border p-2 rounded-md"
        >
          <option value="">-- 카테고리 선택 --</option>
          {categories.map(cat => (
            <option key={cat} value={cat}>{cat}</option>
          ))}
        </select>
      </div>

      {/* 요금제 선택 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">요금제</label>
        <select
          name="planId"
          value={values.planId}
          onChange={e => onPlanSelect(e.target.value)}
          className="w-full border p-2 rounded-md"
          disabled={!values.category}
        >
          <option value="">-- 요금제 선택 --</option>
          {categoryPlans.map(p => (
            <option key={p.id} value={p.id}>
              {p.name} (₩{p.monthlyFee.toLocaleString()})
            </option>
          ))}
        </select>
      </div>

      {/* 단말기 출고가 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">단말기 출고가(₩)</label>
        <input
          type="number"
          name="devicePrice"
          value={values.devicePrice}
          onChange={onChange}
          className="w-full border p-2 rounded-md"
        />
      </div>

      {/* 보조금 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">보조금(₩)</label>
        <input
          type="number"
          name="subsidy"
          value={values.subsidy}
          onChange={onChange}
          className="w-full border p-2 rounded-md"
        />
      </div>

      {/* 할부개월 */}
      <div className="mb-6">
        <label className="block text-sm font-medium mb-1">할부개월</label>
        <select
          name="installments"
          value={values.installments}
          onChange={onChange}
          className="w-full border p-2 rounded-md"
        >
          {[6, 12, 24, 36].map(n => (
            <option key={n} value={n}>{n}개월</option>
          ))}
        </select>
      </div>
    </div>
  );
}