import React, { useState } from 'react';
import { phonePlans } from '../config/phonePlanConfig';

/**
 * PhoneSalesDataSearchForm
 * 데이터 용량별 검색 및 선택 컴포넌트
 */
export default function PhoneSalesDataSearchForm({ value, onSelect }) {
  const [query, setQuery] = useState('');
  // 중복 없는 데이터 용량 목록
  const uniqueData = Array.from(new Set(phonePlans.map(p => p.data)));
  // 입력(query)으로 필터링
  const filtered = uniqueData.filter(d => d.toLowerCase().includes(query.toLowerCase()));

  return (
    <div className="mb-4">
      <label className="block text-sm font-medium mb-1">데이터 검색</label>
      <input
        type="text"
        value={query}
        onChange={e => setQuery(e.target.value)}
        placeholder="예: 무제한, 100GB"
        className="w-full border p-2 rounded-md mb-2"
      />
      <select
        value={value}
        onChange={e => onSelect(e.target.value)}
        className="w-full border p-2 rounded-md"
      >
        <option value="">-- 데이터 선택 --</option>
        {filtered.map(d => (
          <option key={d} value={d}>{d}</option>
        ))}
      </select>
    </div>
  );
}