import React from 'react';

/**
 * PhoneSalesResult
 */
export default function PhoneSalesResult({ totalMonthly, penalty }) {
  return (
    <div className="bg-gray-100 p-4 rounded-lg">
      <p className="text-lg mb-2">
        월 총 지불액: <span className="font-semibold">₩{totalMonthly.toLocaleString()}</span>
      </p>
      <p className="text-lg">
        예상 위약금: <span className="font-semibold">₩{penalty.toLocaleString()}</span>
      </p>
    </div>
  );
}